import gi
gi.require_version('Gtk', '3.0')  # @UndefinedVariable
from gi.repository import Gtk, Gdk, GdkPixbuf, Pango  # @UnresolvedImport

from time import time, sleep


class SplashScreen(object):
    """Full-screen-style splash with centred logo, app name, and version."""

    # --- colour palette (matches the logo) ---
    BG_COLOR   = "#1a2a3a"   # dark blue-grey
    TEXT_COLOR  = "#d0dce8"   # light blue-grey
    ACCENT     = "#e8b84b"   # gold from the Python logo

    def __init__(self, filename, version=""):
        self.window = Gtk.Window(Gtk.WindowType.TOPLEVEL)
        self.window.set_auto_startup_notification(False)

        from mudlab.application.icons import get_icon_list
        self.window.set_default_icon_list(get_icon_list())
        self.window.set_icon_list(get_icon_list())

        self.window.set_title('MudLab')
        self.window.set_skip_taskbar_hint(True)
        self.window.set_position(Gtk.WindowPosition.CENTER)
        self.window.set_decorated(False)
        self.window.set_resizable(False)

        # --- apply dark background via CSS ---
        css = (
            "window.splash-window {"
            "  background-color: %s;"
            "  border-radius: 12px;"
            "}" % self.BG_COLOR
        )
        provider = Gtk.CssProvider()
        provider.load_from_data(css.encode())
        Gtk.StyleContext.add_provider_for_screen(
            Gdk.Screen.get_default(), provider,
            Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION)
        self.window.get_style_context().add_class("splash-window")

        # --- outer frame for a subtle border ---
        frame = Gtk.Frame()
        frame.set_shadow_type(Gtk.ShadowType.NONE)
        self.window.add(frame)

        # --- main vertical box ---
        vbox = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=0)
        vbox.set_margin_top(30)
        vbox.set_margin_bottom(24)
        vbox.set_margin_start(40)
        vbox.set_margin_end(40)
        frame.add(vbox)

        # --- logo image (scaled to 220 px tall, keeping aspect) ---
        try:
            pixbuf = GdkPixbuf.Pixbuf.new_from_file(filename)
            src_w = pixbuf.get_width()
            src_h = pixbuf.get_height()
            target_h = 220
            target_w = int(src_w * target_h / src_h) if src_h else target_h
            pixbuf = pixbuf.scale_simple(
                target_w, target_h, GdkPixbuf.InterpType.BILINEAR)
            logo = Gtk.Image.new_from_pixbuf(pixbuf)
        except Exception:
            logo = Gtk.Image()
        logo.set_margin_bottom(14)
        vbox.pack_start(logo, False, False, 0)

        # --- app title ---
        title = Gtk.Label()
        title.set_markup(
            '<span font_desc="Segoe UI Bold 26" foreground="%s">MudLab</span>'
            % self.TEXT_COLOR)
        title.set_margin_bottom(2)
        vbox.pack_start(title, False, False, 0)

        # --- tag line ---
        tagline = Gtk.Label()
        tagline.set_markup(
            '<span font_desc="Segoe UI 10" foreground="%s">'
            'X-ray Diffraction Analysis of Disordered Layered Minerals'
            '</span>' % self.TEXT_COLOR)
        tagline.set_margin_bottom(10)
        vbox.pack_start(tagline, False, False, 0)

        # --- version ---
        self.version_lbl = Gtk.Label()
        self.version_lbl.set_markup(
            '<span font_desc="Segoe UI 10" foreground="%s">v%s</span>'
            % (self.ACCENT, version))
        self.version_lbl.set_margin_bottom(18)
        vbox.pack_start(self.version_lbl, False, False, 0)

        # --- thin separator line ---
        sep = Gtk.Separator(orientation=Gtk.Orientation.HORIZONTAL)
        sep.set_margin_start(20)
        sep.set_margin_end(20)
        sep.set_margin_bottom(14)
        vbox.pack_start(sep, False, False, 0)

        # --- loading message ---
        self.lbl = Gtk.Label()
        self.lbl.set_markup(
            '<span font_desc="Segoe UI 10" foreground="%s">'
            'Loading ...</span>' % self.TEXT_COLOR)
        vbox.pack_start(self.lbl, False, False, 0)

        self.window.show_all()
        while Gtk.events_pending():
            Gtk.main_iteration()
        self.start_time = time()
        self.closed = False

    def set_message(self, message):
        self.lbl.set_markup(
            '<span font_desc="Segoe UI 10" foreground="%s">%s</span>'
            % (self.TEXT_COLOR, message))
        while Gtk.events_pending():
            Gtk.main_iteration()

    def close(self):
        if not self.closed:
            self.window.set_auto_startup_notification(True)
            while max(5 - (time() - self.start_time), 0) != 0:
                sleep(0.1)
                while Gtk.events_pending():
                    Gtk.main_iteration()
            self.window.destroy()
            del self.window, self.lbl, self.version_lbl
            self.closed = True

    pass  # end of class
